const text = $input.item.json.body.content.toString();
const plain = text.replace(/<[^>]*>/g, ' ');
const m = plain.match(/Ref ID:\s*([0-9]+)/i);

return { refId: m ? m[1] : null };

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.isDraft = 1;
}

return $input.all();

// A new array to hold the output items
const outputItems = [];

// Loop over all input items
for (const item of $input.all()) {
    // Check if the required path exists to avoid errors
    if (item.json.intermediateSteps?.[0]?.action?.toolInput) {
        // Create a new object for the output, selecting only the fields you want
        const newItem = {
            json: {
              toolArgument: item.json.intermediateSteps[0].action.toolInput.variantSku,
