return outputItems;

let subject = '';
let body = '';

const ticketId = String(($json?.fields?.ticketId ?? 'N/A')).trim();
const FOOTER_TEXT = `Ref ID: ${ticketId}`;

const agentResponseText = $input.item.json?.fields?.agentResponse || '';

const trigger = (() => {
  try {
    // Fix typo from earlier: 'is_from_cutomer' -> 'is_from_customer'
    return $('is_from_customer').first().json;
  } catch (e) {
    try {
      const it = $items('Main Email Received Trigger', 0, 0);
      return it?.json;
    } catch (_) {
      return undefined;
    }
  }
})();

const originalEmailBody = trigger?.body?.content || '';
const originalEmailType = (trigger?.body?.contentType || '').toLowerCase();
const receivedDateTime = trigger?.receivedDateTime;
const senderName = trigger?.sender?.emailAddress?.name || '';
const senderEmail = trigger?.sender?.emailAddress?.address || '';
const fallbackThreadSubject = trigger?.subject || '';

/* -------------------- helpers -------------------- */

// Proper HTML escaping for *text content only*
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  }[c]));
}

// Pre-process agent draft: strip wrapping quotes/backticks and normalize LF
function preprocessAgentResponse(s) {
  if (s == null) return '';
  let t = String(s).trim();

  // Strip wrapping quotes
  if ((t.startsWith('"') && t.endsWith('"')) || (t.startsWith("'") && t.endsWith("'"))) {
    t = t.slice(1, -1).trim();
  }

  // Strip ```lang ... ```
  t = t.replace(/^```[\w-]*\s*\r?\n?/, '');   // leading fence + optional language
  t = t.replace(/\r?\n?```$/, '');           // trailing fence

  // Normalize CRLF to LF
  t = t.replace(/\r\n/g, '\n');

  return t;
}

// Return {subject, body} parsed from preprocessed draft
function parseSubjectAndBodyFromDraft(draft) {
  const sm = draft.match(/^\s*Subject:\s*(.+)\s*$/mi);

  if (!sm) {
    return { subject: '', body: draft.trim() };
  }

  const subjectValue = sm[1].trim();
  const lines = draft.split('\n');
  const subjIdx = lines.findIndex(l => /^\s*Subject:/i.test(l));

  let i = subjIdx + 1;
  while (i < lines.length && lines[i].trim() === '') i++;

  const bodyValue = lines.slice(i).join('\n').trim();

  return { subject: subjectValue, body: bodyValue };
}

// Keep existing formatting; no localization beyond this
function formatDate(dateString) {
  if (!dateString) return '';
  const date = new Date(dateString);
  return date.toLocaleString('en-US', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    timeZoneName: 'short',
  });
}

// Decode one level of common entities toward *real* HTML
function decodeCommonEntitiesOnce(text) {
  const map = {
    '&amp;lt;': '<', '&amp;gt;': '>', '&amp;quot;': '"', '&amp;#39;': "'", '&amp;amp;': '&', '&amp;nbsp;': '\u00A0',
    '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'", '&amp;': '&', '&nbsp;': '\u00A0',
  };
  return String(text).replace(/&(amp;)?(?:lt|gt|quot|#39|amp|nbsp);/g, m => map[m] || m);
}

// Decode up to 2 passes (common for doubly-encoded bodies)
function decodeEntitiesToHtml(text, maxPasses = 2) {
  let prev = String(text);
  for (let i = 0; i < maxPasses; i++) {
    const next = decodeCommonEntitiesOnce(prev);
    if (next === prev) break;
    prev = next;
  }
  return prev;
}

// Extract <body> content if present; otherwise entire HTML
function extractBodyHtml(html) {
  const m = String(html).match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  return (m ? m[1] : html).trim();
}

/**
 * Sanitize HTML but keep images.
 * - Removes risky tags: script/style/meta/link/iframe/object/embed/form
 * - Strips event handlers (onclick, etc.)
 * - Allows href schemes: http(s), mailto:, cid:
 * - Allows img src schemes: http(s), cid:, data:image
 * - Optionally drops likely tracking beacons (1x1 or hidden imgs)
 */
function sanitizeEmailHtml(html, opts = { allowImages: true, dropTrackingBeacons: true }) {
  let h = String(html);
  const { allowImages, dropTrackingBeacons } = opts;

  // Remove entire blocks for risky tags
  h = h.replace(/<(script|style|meta|link|iframe|object|embed|form)\b[^>]*>[\s\S]*?<\/\1>/gi, '');
  // Remove standalone risky/self-closing variants
  h = h.replace(/<(script|style|meta|link|iframe|object|embed|form)\b[^>]*\/?>/gi, '');

  // Strip event handlers like onclick="..."
  h = h.replace(/\s+on\w+=(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '');

  // Neutralize non-allowed HREF schemes
  h = h.replace(/\s+href\s*=\s*"(?!https?:|mailto:|cid:)[^"]*"/gi, ' href="#"');
  h = h.replace(/\s+href\s*=\s*'(?!https?:|mailto:|cid:)[^']*'/gi, " href='#'");

  if (allowImages) {
    // For <img>, limit src to http(s), cid:, or data:image (inline)
    h = h.replace(/(<img\b[^>]*\s)src\s*=\s*"(?:(?!https?:|cid:|data:image)[^"]*)"/gi, '$1src=""');
    h = h.replace(/(<img\b[^>]*\s)src\s*=\s*'(?:(?!https?:|cid:|data:image)[^']*)'/gi, "$1src=''");

    if (dropTrackingBeacons) {
      // Remove likely tracking beacons: 1x1 or hidden
      h = h.replace(/<img\b([^>]*)>/gi, (m, attrs) => {
        const a = attrs.toLowerCase();
        const has1x1 = /\bwidth\s*=\s*["']?1["']?\b/.test(a) && /\bheight\s*=\s*["']?1["']?\b/.test(a);
        const hidden = /display\s*:\s*none|visibility\s*:\s*hidden|opacity\s*:\s*0/.test(a);
        return (has1x1 || hidden) ? '' : m;
      });
    }
  } else {
    // Strip images entirely
    h = h.replace(/<img\b[^>]*>/gi, '');
  }

  return h;
}

// Convert HTML to readable text (for plain-text fallback)
function htmlToText(html) {
  return String(html)
    .replace(/<a\b[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, (m, href, text) => `${text} (${href})`)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<li>/gi, '• ')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/\u00A0/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function tidyText(text) {
  return String(text)
    .replace(/\r\n/g, '\n')
    .replace(/\t/g, '  ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function indentQuoted(text) {
  return String(text).split('\n').map(l => '    ' + l).join('\n');
}

/* -------------------- 1) Parse Agent Draft -------------------- */

const draft = preprocessAgentResponse(agentResponseText);
const parsed = parseSubjectAndBodyFromDraft(draft);
subject = parsed.subject || fallbackThreadSubject || '(No subject)';
body = parsed.body || '';

/* Agent body as HTML (escape text, then convert newlines to <br>) */
const agentBodyHtml =
  `<div style="font-family:Segoe UI, Arial, sans-serif; line-height:1.5; color:#111827;">` +
    (body ? escapeHtml(body).replace(/\n/g, '<br>') : '') +
  `</div>`;

/* -------------------- 2) Build "Original Message" quoted block -------------------- */

const headerHtml =
  `<div style="margin:0 0 8px 0; font-size:12px; color:#6B7280;">` +
    `<div style="font-weight:600; color:#374151;">— Original message —</div>` +
    ((senderName || senderEmail) ? `<div>From: ${escapeHtml(senderName)} &lt;${escapeHtml(senderEmail)}&gt;</div>` : '') +
    (receivedDateTime ? `<div>Sent: ${escapeHtml(formatDate(receivedDateTime))}</div>` : '') +
  `</div>`;

const headerText =
  `\n\n--- Original Message ---\n` +
  ((senderName || senderEmail) ? `From: ${senderName} <${senderEmail}>\n` : '') +
  (receivedDateTime ? `Sent: ${formatDate(receivedDateTime)}\n` : '') +
  `\n`;

let quotedOriginalHtml = '';
let quotedOriginalText = '';

if (originalEmailBody) {
  if (originalEmailType === 'html') {
    // Reach real HTML (handle once/twice-encoded bodies)
    let htmlCandidate = originalEmailBody;
    if (!/[<>]/.test(htmlCandidate)) {
      htmlCandidate = decodeEntitiesToHtml(htmlCandidate, 2);
    }

    // Extract <body> content and sanitize, but keep images
    let html = extractBodyHtml(htmlCandidate);
    html = sanitizeEmailHtml(html, { allowImages: true, dropTrackingBeacons: false });

    quotedOriginalHtml =
      `<blockquote style="margin:16px 0 0 0; padding-left:12px; border-left:3px solid #e5e7eb; color:#374151;">` +
        headerHtml +
        html + // real HTML preserved (sanitized)
      `</blockquote>`;

    quotedOriginalText = headerText + htmlToText(html);

  } else {
    // Plain text original
    const cleanText = tidyText(originalEmailBody);
    quotedOriginalText = headerText + indentQuoted(cleanText);

    quotedOriginalHtml =
      `<blockquote style="margin:16px 0 0 0; padding-left:12px; border-left:3px solid #e5e7eb; color:#374151;">` +
        headerHtml +
        `<pre style="white-space:pre-wrap; font-family:Segoe UI, Arial, sans-serif; margin:0;">${escapeHtml(cleanText)}</pre>` +
      `</blockquote>`;
  }
}

/* -------------------- 3) Footer -------------------- */

const footerHtml =
  `<div style="margin-top:16px; font-size:12px; color:#6B7280;">${escapeHtml(FOOTER_TEXT)}</div>`;

/* -------------------- 4) Final HTML and Plain Text bodies -------------------- */

const finalHtml =
  `<div style="font-family:Segoe UI, Arial, sans-serif; line-height:1.5; color:#111827;">` +
    agentBodyHtml +
    quotedOriginalHtml +
    footerHtml +
  `</div>`;

const finalText =
  (body ? tidyText(body) : '') +
  (quotedOriginalText ? `\n\n${quotedOriginalText}` : '') +
  `\n\n${FOOTER_TEXT}`;



// Extract all cid content IDs used by cid:...
function extractCidList(html) {
  const ids = new Set();
  const re = /<img\b[^>]*\bsrc\s*=\s*["']cid:([^"']+)["']/gi;
  let m;
  while ((m = re.exec(html))) {
    ids.add(m[1]);
  }
  return Array.from(ids);
}

const cidList = extractCidList(finalHtml);


/* -------------------- 5) Output fields -------------------- */

$input.item.json['Subject']  = subject;
$input.item.json['Body']     = finalText;   // Plain text fallback
$input.item.json['BodyHtml'] = finalHtml;   // True HTML for Outlook
$input.item.json['InlineContentIds']  = cidList;     // ["ii_mgo7f4qv0", ...]
$input.item.json['OriginalMessageId'] = trigger?.id; // Needed to fetch attachments


return $input.item;
